package com.yigongbao.backup.common;

import cn.dev33.satoken.exception.NotLoginException; import cn.dev33.satoken.exception.NotRoleException;
import jakarta.servlet.http.HttpServletRequest; import lombok.extern.slf4j.Slf4j; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.ExceptionHandler; import org.springframework.web.bind.annotation.RestControllerAdvice; import org.springframework.web.multipart.MaxUploadSizeExceededException; import java.util.UUID;

/** 将业务异常转换为稳定 JSON 错误信封并避免泄露堆栈。 */
@Slf4j
@RestControllerAdvice
public class GlobalExceptionHandler {
 @ExceptionHandler(NotLoginException.class) public org.springframework.http.ResponseEntity<ApiResponse<Void>> notLoggedIn(NotLoginException e,HttpServletRequest r){String requestId=UUID.randomUUID().toString();log.warn("认证失效 requestId={} method={} uri={} type={}",requestId,r.getMethod(),r.getRequestURI(),e.getType());return response(HttpStatus.UNAUTHORIZED,"UNAUTHORIZED","登录状态已失效，请重新登录",requestId);}
 @ExceptionHandler(NotRoleException.class) public org.springframework.http.ResponseEntity<ApiResponse<Void>> forbidden(NotRoleException e,HttpServletRequest r){String requestId=UUID.randomUUID().toString();log.warn("权限不足 requestId={} method={} uri={} role={}",requestId,r.getMethod(),r.getRequestURI(),e.getRole());return response(HttpStatus.FORBIDDEN,"FORBIDDEN","当前账号无权执行该操作",requestId);}
 @ExceptionHandler(com.yigongbao.backup.account.LoginThrottleService.LoginThrottledException.class) public org.springframework.http.ResponseEntity<ApiResponse<Void>> loginThrottled(com.yigongbao.backup.account.LoginThrottleService.LoginThrottledException e,HttpServletRequest r){String requestId=UUID.randomUUID().toString();log.warn("登录请求被限流 requestId={} remoteAddress={}",requestId,r.getRemoteAddr());return response(HttpStatus.TOO_MANY_REQUESTS,"LOGIN_THROTTLED",e.getMessage(),requestId);}
 @ExceptionHandler(IllegalArgumentException.class) public org.springframework.http.ResponseEntity<ApiResponse<Void>> bad(IllegalArgumentException e,HttpServletRequest r){String requestId=UUID.randomUUID().toString();log.warn("请求参数校验失败 requestId={} method={} uri={} message={}",requestId,r.getMethod(),r.getRequestURI(),e.getMessage());return response(HttpStatus.BAD_REQUEST,"INVALID_ARGUMENT",e.getMessage(),requestId);}
 @ExceptionHandler(IllegalStateException.class) public org.springframework.http.ResponseEntity<ApiResponse<Void>> conflict(IllegalStateException e,HttpServletRequest r){String requestId=UUID.randomUUID().toString();log.warn("请求状态冲突 requestId={} method={} uri={} message={}",requestId,r.getMethod(),r.getRequestURI(),e.getMessage());return response(HttpStatus.CONFLICT,"STATE_CONFLICT",e.getMessage(),requestId);}
 @ExceptionHandler(MaxUploadSizeExceededException.class) public org.springframework.http.ResponseEntity<ApiResponse<Void>> uploadTooLarge(MaxUploadSizeExceededException e,HttpServletRequest r){String requestId=UUID.randomUUID().toString();log.warn("补传文件超过HTTP上传上限 requestId={} method={} uri={} limit={}",requestId,r.getMethod(),r.getRequestURI(),e.getMaxUploadSize());return response(HttpStatus.PAYLOAD_TOO_LARGE,"UPLOAD_TOO_LARGE","补传文件超过系统上传上限，请压缩文件或调整上传配置",requestId);}
 @ExceptionHandler(Exception.class) public org.springframework.http.ResponseEntity<ApiResponse<Void>> error(Exception e,HttpServletRequest r){String requestId=UUID.randomUUID().toString();log.error("请求处理失败 requestId={} method={} uri={}",requestId,r.getMethod(),r.getRequestURI(),e);return response(HttpStatus.INTERNAL_SERVER_ERROR,"INTERNAL_ERROR","服务处理失败",requestId);}
 private org.springframework.http.ResponseEntity<ApiResponse<Void>> response(HttpStatus status,String code,String msg,String requestId){return org.springframework.http.ResponseEntity.status(status).body(new ApiResponse<>(code,msg,requestId,null));}
}
